import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"development/testing.md","filePath":"development/testing.md"}'),r={name:"development/testing.md"};function o(d,e,i,c,l,u){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>Jest runs TypeScript tests from <code>apps/web/src</code> using the root <code>jest.config.js</code>. Install dependencies with <code>npm ci</code>, then run commands from the repository root.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>npm test -- --runInBand</code></td><td>Run all suites serially</td></tr><tr><td><code>npm test -- --runInBand --runTestsByPath apps/web/src/lib/__tests__/daily-usage.test.ts</code></td><td>Run one existing suite</td></tr><tr><td><code>npm run test:watch</code></td><td>Re-run tests while editing</td></tr><tr><td><code>npm run test:coverage</code></td><td>Generate current text, HTML and LCOV coverage in <code>coverage/</code></td></tr><tr><td><code>npm run test:ci</code></td><td>Run serially with coverage</td></tr><tr><td><code>npm run lint</code></td><td>Lint web source and Next.js configuration</td></tr><tr><td><code>npm run build</code></td><td>Verify the Next.js production build</td></tr><tr><td><code>npm run docs:build</code></td><td>Build VitePress documentation</td></tr></tbody></table><p>The production build uses the web environment configured in <a href="https://github.com/COOLmanYT/skystyle/blob/main/SETUP.md" target="_blank" rel="noreferrer">setup</a>. Jest uses test credentials instead of real provider keys.</p><h2 id="test-layout-and-mocks" tabindex="-1">Test layout and mocks <a class="header-anchor" href="#test-layout-and-mocks" aria-label="Permalink to &quot;Test layout and mocks&quot;">​</a></h2><ul><li><code>apps/web/src/__tests__/setup.ts</code> supplies test environment variables and shared Next.js, fetch, and localStorage mocks.</li><li><code>apps/web/src/__tests__/mocks.ts</code> contains shared fixtures.</li><li>Library, component and API suites are colocated in their own <code>__tests__</code> directories.</li><li>Supabase and Auth.js are mocked by the suites that use them; they are not universally mocked by global setup.</li></ul><p>Jest uses a Node environment. Component suites must explicitly provide any DOM or rendering support they require. Account and usage suites explicitly select the behavior they exercise; adapter suites unmock the module when needed.</p><h2 id="writing-useful-tests" tabindex="-1">Writing useful tests <a class="header-anchor" href="#writing-useful-tests" aria-label="Permalink to &quot;Writing useful tests&quot;">​</a></h2><p>Choose an existing suite near the code you change as a starting point. Assert observable behavior: response status and body, ownership rejection, accounting changes, or user-visible results. Include the relevant error and boundary cases.</p><p>For route tests, mock <code>@/auth</code> and database/provider operations deliberately. Supply actual request data and fixtures defined in the test; use the request methods the handler reads. Reset changed environment variables and mocks so a suite does not affect the next one. The test filename should end in <code>.test.ts</code> or <code>.test.tsx</code>.</p><p>Avoid real network calls, production secrets, or production writes in Jest. Database regression checks have a separate <a href="https://github.com/COOLmanYT/skystyle/blob/main/supabase/tests/README.md" target="_blank" rel="noreferrer">rollback-only SQL fixture guide</a>; they are not run by <code>npm test</code> and require their own review.</p><h2 id="verification-evidence" tabindex="-1">Verification evidence <a class="header-anchor" href="#verification-evidence" aria-label="Permalink to &quot;Verification evidence&quot;">​</a></h2><p>Record the date, revision, commands, and failures for the candidate you tested. Rerun checks for the current checkout before claiming it passes. Generate coverage before quoting a percentage.</p><p>A passing mocked suite does not prove live OAuth callbacks, provider credentials, shopping-source acceptance, mobile behavior, keyboard access, or a safe accounting cutover. Record browser and real-account acceptance separately with the exact tested domain and deployment revision. Automated tests do not enable purchases or change account entitlements.</p><p>VitePress rejects missing internal page links. Check image paths, external URLs and the rendered navigation as well. Edit Markdown source rather than generated HTML; new build output is ignored by Git.</p>',16)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
